// 이전 버전 호환성 유지용 기본 50문항
const FIFTY_DILEMMAS = DAD_DILEMMAS;


// ========================================================
// 4개 페르소나별 시나리오 뱅크 맵
// ========================================================
const PERSONA_BANKS = {
  dad: DAD_DILEMMAS,
  father: DAD_DILEMMAS,
  mom: MOM_DILEMMAS,
  mother: MOM_DILEMMAS,
  son: SON_DILEMMAS,
  daughter: DAUGHTER_DILEMMAS
};

// ========================================================
// 실시간 동적 질문 생성 엔진 (Dynamic Question Engine)
// - 매 검사마다 겹치지 않는 신선한 질문 세트 구성
// - 15문항(스피드), 30문항(밸런스), 50문항(심층) 선택 지원
// - 5대 테마 및 10대 가치관의 균등한 확률적 노출 보장
// - 선택지 순서 무작위 셔플을 통한 신선도 유지
// ========================================================
function generateDynamicQuestions(personaId = 'dad', count = 30) {
  const normalizedPersona = (personaId && PERSONA_BANKS[personaId]) ? personaId : 'dad';
  const bank = PERSONA_BANKS[normalizedPersona];
  
  // 지원하는 문항 수: 15, 30, 50 (기본 30)
  const targetCount = [15, 30, 50].includes(Number(count)) ? Number(count) : 30;
  const perTheme = targetCount / 5; // 3, 6, 10

  // 1. 테마별 그룹화
  const byTheme = {
    theme_1: [],
    theme_2: [],
    theme_3: [],
    theme_4: [],
    theme_5: []
  };

  bank.forEach(q => {
    if (byTheme[q.themeId]) {
      byTheme[q.themeId].push(q);
    }
  });

  const selectedQuestions = [];

  // 2. 테마별 공정 무작위 샘플링 (Fisher-Yates)
  THEMES.forEach(t => {
    const pool = [...byTheme[t.id]];
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    const picked = pool.slice(0, perTheme);
    selectedQuestions.push(...picked);
  });

  // 3. 문항 순서 및 선택지 순서 무작위 셔플 (동적 세션 생성)
  // 단, 테마의 자연스러운 흐름(일상 -> 위기 -> 관계 -> 호기심 -> 유희)을 유지하기 위해
  // 테마 내에서 셔플된 질문들을 배치하고, 각 문항의 4개 선택지 순서를 셔플합니다.
  return selectedQuestions.map((q, idx) => {
    const clonedOptions = q.options.map(opt => ({ ...opt }));
    // 선택지 순서 셔플
    for (let i = clonedOptions.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [clonedOptions[i], clonedOptions[j]] = [clonedOptions[j], clonedOptions[i]];
    }

    return {
      ...q,
      personaId: normalizedPersona,
      sessionIndex: idx + 1,
      totalInSession: targetCount,
      options: clonedOptions
    };
  });
}


